#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * Rule 110 cellular automaton simulation.
 * The original binary (prog59_rule110) expects two command‑line arguments:
 *   1. A string consisting only of the characters '0' and '1' – the initial row.
 *   2. A non‑negative integer specifying how many generations to compute.
 * The program validates the input, limits the row length to 60 cells and the
 * number of generations to 200, and prints the initial row followed by each
 * subsequent generation, one per line.  On any validation error it prints
 * "INVALID_INPUT" (followed by a newline) and exits.
 */

static const int RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    0, /* 100 */
    1, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

int main(int argc, char *argv[])
{
    /* Validate argument count */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *row_str = argv[1];
    size_t len = strlen(row_str);

    /* Row length must be between 1 and 60 and contain only '0' or '1' */
    if (len == 0 || len > 60) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (row_str[i] != '0' && row_str[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* Parse number of generations */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps < 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps > 200) {
        steps = 200;   /* the original program caps the value */
    }

    /* Buffers for the current and next rows – one extra byte for the terminating '\0' */
    char cur[61];
    char nxt[61];
    memcpy(cur, row_str, len);
    cur[len] = '\0';

    /* Print the initial row */
    puts(cur);

    for (long gen = 0; gen < steps; ++gen) {
        /* Compute next generation */
        for (size_t i = 0; i < len; ++i) {
            int left  = (i == 0) ? 0 : (cur[i-1] - '0');
            int self  = cur[i] - '0';
            int right = (i == len-1) ? 0 : (cur[i+1] - '0');
            int idx = (left << 2) | (self << 1) | right;   /* left*4 + self*2 + right */
            nxt[i] = (char)(RULE110[idx] + '0');
        }
        nxt[len] = '\0';
        puts(nxt);
        /* Swap buffers for the next iteration */
        memcpy(cur, nxt, len + 1);
    }

    return 0;
}
